code.C:
#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        int first = 1;
        for (int i = 1; i <= n; i += 2) {
            if (!first) printf(" ");
            printf("%d", i);
            first = 0;
        }
        printf("\n");
    }
    return 0;
}

