            if (!first) cout << " ";
            cout << i;
            first = false;
        }
        cout << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= n; i += 2) {
                if (i > 1) sb.append(" ");
                sb.append(i);
            }
            System.out.println(sb.toString());
        }
    }
}

